import { MakeLogicType, actions, kea, path, reducers } from 'kea'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inFlightRequestsLogicValues {
    inFlightRequests: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface inFlightRequestsLogicActions {
    requestFinished: (failed: boolean) => {
        failed: boolean
    }
    requestStarted: () => {
        startedAt: number
    }
}

export type inFlightRequestsLogicType = MakeLogicType<inFlightRequestsLogicValues, inFlightRequestsLogicActions>

export const inFlightRequestsLogic = kea<inFlightRequestsLogicType>([
    path(['lib', 'logic', 'inFlightRequestsLogic']),
    actions({
        requestStarted: () => ({ startedAt: performance.now() }),
        requestFinished: (failed: boolean) => ({ failed }),
    }),
    reducers({
        inFlightRequests: [
            0,
            {
                requestStarted: (count) => count + 1,
                requestFinished: (count) => count - 1,
            },
        ],
    }),
])

export function startTrackedRequest(): (failed: boolean) => void {
    const tracker = inFlightRequestsLogic.findMounted()
    if (!tracker) {
        return () => {}
    }
    const { requestStarted, requestFinished } = tracker.actions
    requestStarted()
    return requestFinished
}
